def rows_to_docids(
    rows
):

    result = []

    for row in rows:

        row = int(
            row
        )

        if row < 0:

            continue

        result.append(
            ROW_TO_DOCID[
                row
            ]
        )

    return result


def ann_recall_at_k(
    exact_rows,
    approx_rows,
    k
):

    exact_set = set(
        exact_rows[:k]
    )

    approx_set = set(
        approx_rows[:k]
    )

    return (
        len(
            exact_set
            &
            approx_set
        )
        /
        float(
            k
        )
    )


def ndcg_at_k(
    retrieved_docids,
    query_key,
    k=10
):

    query_qrels = qrels.get(
        query_key,
        {}
    )

    dcg = 0.0

    for rank, docid in enumerate(
        retrieved_docids[:k]
    ):

        rel = int(
            query_qrels.get(
                docid,
                0
            )
        )

        gain = (
            (2 ** rel)
            -
            1
        )

        dcg += (
            gain
            /
            math.log2(
                rank + 2
            )
        )


    ideal = sorted(
        [
            int(rel)
            for rel
            in query_qrels.values()
            if rel > 0
        ],
        reverse=True
    )[:k]


    idcg = 0.0

    for rank, rel in enumerate(
        ideal
    ):

        gain = (
            (2 ** rel)
            -
            1
        )

        idcg += (
            gain
            /
            math.log2(
                rank + 2
            )
        )


    if idcg <= 0:

        return 0.0


    return (
        dcg
        /
        idcg
    )


def recall_at_k(
    retrieved_docids,
    query_key,
    k=100
):

    relevant = {

        docid

        for docid, rel
        in qrels.get(
            query_key,
            {}
        ).items()

        if rel > 0
    }


    if len(
        relevant
    ) == 0:

        return 0.0


    retrieved = set(
        retrieved_docids[:k]
    )


    return (
        len(
            relevant
            &
            retrieved
        )
        /
        len(
            relevant
        )
    )


def mrr_at_k(
    retrieved_docids,
    query_key,
    k=10
):

    query_qrels = qrels.get(
        query_key,
        {}
    )

    for rank, docid in enumerate(
        retrieved_docids[:k]
    ):

        if query_qrels.get(
            docid,
            0
        ) > 0:

            return (
                1.0
                /
                (
                    rank + 1
                )
            )

    return 0.0


# ============================================================
# 15. STATISTICAL FUNCTIONS
# ============================================================

def bootstrap_mean_ci(
    values,
    n_boot,
    seed
):

    values = np.asarray(
        values,
        dtype=np.float64
    )

    values = values[
        np.isfinite(
            values
        )
    ]


    if len(
        values
    ) == 0:

        return (
            np.nan,
            np.nan,
            np.nan
        )


    rng = np.random.default_rng(
        seed
    )


    estimates = np.empty(
        n_boot,
        dtype=np.float64
    )


    n = len(
        values
    )


    for i in range(
        n_boot
    ):

        sample = values[
            rng.integers(
                0,
                n,
                size=n
            )
        ]

        estimates[
            i
        ] = np.mean(
            sample
        )


    return (
        float(
            np.mean(
                values
            )
        ),
        float(
            np.quantile(
                estimates,
                0.025
            )
        ),
        float(
            np.quantile(
                estimates,
                0.975
            )
        )
    )


def bootstrap_proportion_ci(
    binary_values,
    n_boot,
    seed
):

    return bootstrap_mean_ci(
        binary_values,
        n_boot,
        seed
    )


def paired_randomization_pvalue(
    differences,
    n_permutations,
    seed
):

    """
    Two-sided paired sign-randomization test.

    Null:
        direction of the per-query difference is arbitrary.

    This keeps query-level pairing intact.
    """

    differences = np.asarray(
        differences,
        dtype=np.float64
    )


    differences = differences[
        np.isfinite(
            differences
        )
    ]


    if len(
        differences
    ) == 0:

        return np.nan


    observed = abs(
        np.mean(
            differences
        )
    )


    if observed == 0:

        return 1.0


    rng = np.random.default_rng(
        seed
    )


    extreme = 0


    for _ in range(
        n_permutations
    ):

        signs = rng.choice(
            [
                -1.0,
                1.0
            ],
            size=len(
                differences
            )
        )

        permuted = abs(
            np.mean(
                differences
                *
                signs
            )
        )


        if permuted >= observed:

            extreme += 1


    return (
        extreme + 1
    ) / (
        n_permutations + 1
    )


