# ============================================================
# 17. GENERIC HNSW SWEEP
# ============================================================

def run_search_sweep(
    task_name,
    search_k,
    ef_values
):

    all_rows = []

    summary_rows = []


    print(
        "\n"
        +
        "=" * 100
    )

    print(
        task_name
    )

    print(
        "=" * 100
    )


    for ef in ef_values:

        print(
            "\n"
            +
            "-" * 80
        )

        print(
            f"{task_name}: "
            f"k={search_k}, "
            f"efSearch={ef}"
        )

        print(
            "-" * 80
        )


        hnsw_index.hnsw.efSearch = int(
            ef
        )


        # ----------------------------------------------------
        # WARM-UP
        # ----------------------------------------------------

        warmup_count = min(
            30,
            N_QUERIES
        )


        for i in range(
            warmup_count
        ):

            hnsw_index.search(

                np.ascontiguousarray(

                    query_embeddings[
                        i:i + 1
                    ],

                    dtype=np.float32
                ),

                search_k
            )


        # ----------------------------------------------------
        # STORAGE
        # ----------------------------------------------------

        latency = np.zeros(

            (
                args.repeats,
                N_QUERIES
            ),

            dtype=np.float64
        )


        first_indices = np.empty(

            (
                N_QUERIES,
                search_k
            ),

            dtype=np.int64
        )


        distance_computations = np.full(

            N_QUERIES,

            np.nan
        )


        hnsw_hops = np.full(

            N_QUERIES,

            np.nan
        )


        # ----------------------------------------------------
        # REPEATED RANDOMIZED TIMING
        # ----------------------------------------------------

        for repeat in range(
            args.repeats
        ):

            order = np.arange(
                N_QUERIES
            )


            repeat_rng = np.random.default_rng(

                SEED
                +
                ef
                +
                search_k * 1000
                +
                repeat
            )


            repeat_rng.shuffle(
                order
            )


            for query_index in order:

                query_vector = np.ascontiguousarray(

                    query_embeddings[
                        query_index:
                        query_index + 1
                    ],

                    dtype=np.float32
                )


                if repeat == 0:

                    reset_hnsw_stats()


                start_ns = (
                    time.perf_counter_ns()
                )


                _, indices = hnsw_index.search(

                    query_vector,

                    search_k
                )


                end_ns = (
                    time.perf_counter_ns()
                )


                latency[
                    repeat,
                    query_index
                ] = (

                    end_ns
                    -
                    start_ns

                ) / 1_000_000.0


                if repeat == 0:

                    first_indices[
                        query_index
                    ] = indices[
                        0
                    ]


                    (
                        ndis,
                        nhops
                    ) = get_hnsw_stats()


                    distance_computations[
                        query_index
                    ] = ndis


                    hnsw_hops[
                        query_index
                    ] = nhops


        # ----------------------------------------------------
        # QUERY-LEVEL METRICS
        # ----------------------------------------------------

        query_rows = []


        for i, query_row in query_df.iterrows():

            query_key = query_row[
                "query_key"
            ]


            approximate_indices = (
                first_indices[
                    i
                ]
            )


            exact_rows = (
                exact_indices[
                    i
                ]
            )


            approximate_docids = rows_to_docids(
                approximate_indices
            )


            exact_record = exact_map.loc[
                query_key
            ]


            record = {

                "task":
                    task_name,

                "query_key":
                    query_key,

                "source":
                    query_row[
                        "source"
                    ],

                "search_k":
                    search_k,

                "efSearch":
                    int(
                        ef
                    ),

                "mean_latency_ms":
                    float(
                        latency[
                            :,
                            i
                        ].mean()
                    ),

                "distance_computations":
                    distance_computations[
                        i
                    ],

                "hnsw_hops":
                    hnsw_hops[
                        i
                    ],

                "boundary_gap_10_11":
                    exact_record[
                        "boundary_gap_10_11"
                    ],

                "top1_top10_gap":
                    exact_record[
                        "top1_top10_gap"
                    ],

                "mean_top10_similarity":
                    exact_record[
                        "mean_top10_similarity"
                    ],

                "positive_qrel_count":
                    exact_record[
                        "positive_qrel_count"
                    ]
            }


            # ------------------------------------------------
            # TOP-10 TASK
            # ------------------------------------------------

            if search_k == 10:

                ann_recall10 = ann_recall_at_k(

                    exact_rows,

                    approximate_indices,

                    10
                )


                ndcg10 = ndcg_at_k(

                    approximate_docids,

                    query_key,

                    10
                )


                mrr10 = mrr_at_k(

                    approximate_docids,

                    query_key,

                    10
                )


                ndcg_loss = max(

                    0.0,

                    float(
                        exact_record[
                            "exact_nDCG@10"
                        ]
                    )

                    -

                    ndcg10
                )


                mrr_loss = max(

                    0.0,

                    float(
                        exact_record[
                            "exact_MRR@10"
                        ]
                    )

                    -

                    mrr10
                )


                record.update({

                    "ANN_Recall@10":
                        ann_recall10,

                    "nDCG@10":
                        ndcg10,

                    "MRR@10":
                        mrr10,

                    "nDCG_loss":
                        ndcg_loss,

                    "MRR_loss":
                        mrr_loss
                })


            # ------------------------------------------------
            # TOP-100 TASK
            # ------------------------------------------------

            if search_k == 100:

                ann_recall100 = ann_recall_at_k(

                    exact_rows,

                    approximate_indices,

                    100
                )


                recall100 = recall_at_k(

                    approximate_docids,

                    query_key,

                    100
                )


                ndcg10 = ndcg_at_k(

                    approximate_docids,

                    query_key,

                    10
                )


                recall100_loss = max(

                    0.0,

                    float(
                        exact_record[
                            "exact_Recall@100"
                        ]
                    )

                    -

                    recall100
                )


                record.update({

                    "ANN_Recall@100":
                        ann_recall100,

                    "Recall@100":
                        recall100,

                    "nDCG@10":
                        ndcg10,

                    "Recall100_loss":
                        recall100_loss
                })


            query_rows.append(
                record
            )


            all_rows.append(
                record
            )


        ef_df = pd.DataFrame(
            query_rows
        )


        # ----------------------------------------------------
        # LATENCY CONFIDENCE INTERVAL
        # ----------------------------------------------------

        (
            latency_mean,
            latency_ci_low,
            latency_ci_high
        ) = bootstrap_mean_ci(

            ef_df[
                "mean_latency_ms"
            ].values,

            args.bootstrap,

            SEED + ef + search_k
        )


        summary_record = {

            "task":
                task_name,

            "search_k":
                search_k,

            "efSearch":
                int(
                    ef
                ),

            "queries":
                len(
                    ef_df
                ),

            "mean_latency_ms":
                latency_mean,

            "latency_95CI_low":
                latency_ci_low,

            "latency_95CI_high":
                latency_ci_high,

            "p50_latency_ms":
                ef_df[
                    "mean_latency_ms"
                ].quantile(
                    0.50
                ),

            "p95_latency_ms":
                ef_df[
                    "mean_latency_ms"
                ].quantile(
                    0.95
                ),

            "p99_latency_ms":
                ef_df[
                    "mean_latency_ms"
                ].quantile(
                    0.99
                ),

            "mean_distance_computations":
                ef_df[
                    "distance_computations"
                ].mean(),

            "mean_hnsw_hops":
                ef_df[
                    "hnsw_hops"
                ].mean()
        }


        if search_k == 10:

            summary_record.update({

                "mean_ANN_Recall@10":
                    ef_df[
                        "ANN_Recall@10"
                    ].mean(),

                "mean_nDCG@10":
                    ef_df[
                        "nDCG@10"
                    ].mean(),

                "mean_MRR@10":
                    ef_df[
                        "MRR@10"
                    ].mean()
            })


        if search_k == 100:

            summary_record.update({

                "mean_ANN_Recall@100":
                    ef_df[
                        "ANN_Recall@100"
                    ].mean(),

                "mean_Recall@100":
                    ef_df[
                        "Recall@100"
                    ].mean(),

                "mean_nDCG@10":
                    ef_df[
                        "nDCG@10"
                    ].mean()
            })


        summary_rows.append(
            summary_record
        )


    return (
        pd.DataFrame(
            all_rows
        ),
        pd.DataFrame(
            summary_rows
        )
    )


