# ============================================================
# 20. GENERIC ORACLE COMPARISON
# ============================================================

def oracle_comparison(
    df,
    ef_values,
    ann_column,
    ir_loss_column,
    ir_tolerance,
    source_filter=None
):

    working = df.copy()


    if source_filter is not None:

        working = working[
            working[
                "source"
            ]
            ==
            source_filter
        ].copy()


    oracle_rows = []


    for query_key, group in working.groupby(
        "query_key"
    ):

        group = group.sort_values(
            "efSearch"
        )


        ann_safe_rows = group[

            group[
                ann_column
            ]
            >=
            ANN_TARGET
        ]


        ir_safe_rows = group[

            group[
                ir_loss_column
            ]
            <=
            ir_tolerance
        ]


        ann_found = len(
            ann_safe_rows
        ) > 0


        ir_found = len(
            ir_safe_rows
        ) > 0


        if ann_found:

            min_ann = int(

                ann_safe_rows.iloc[
                    0
                ][
                    "efSearch"
                ]
            )

        else:

            min_ann = int(
                ef_values[-1]
            )


        if ir_found:

            min_ir = int(

                ir_safe_rows.iloc[
                    0
                ][
                    "efSearch"
                ]
            )

        else:

            min_ir = int(
                ef_values[-1]
            )


        first = group.iloc[
            0
        ]


        oracle_rows.append({

            "query_key":
                query_key,

            "source":
                first[
                    "source"
                ],

            "min_ANN_safe_ef":
                min_ann,

            "min_IR_safe_ef":
                min_ir,

            "ANN_safe_found":
                int(
                    ann_found
                ),

            "IR_safe_found":
                int(
                    ir_found
                ),

            # positive:
            # ANN criterion requires more work
            "ANN_minus_IR_budget":
                min_ann
                -
                min_ir,

            "IR_allows_lower":
                int(
                    min_ir
                    <
                    min_ann
                ),

            "same_budget":
                int(
                    min_ir
                    ==
                    min_ann
                ),

            "IR_requires_higher":
                int(
                    min_ir
                    >
                    min_ann
                )
        })


    return pd.DataFrame(
        oracle_rows
    )


# ============================================================
# 21. ORACLE SUMMARY + STATISTICS
# ============================================================

def summarize_oracle(
    oracle_df,
    task_name,
    tolerance,
    source_name
):

    differences = oracle_df[
        "ANN_minus_IR_budget"
    ].to_numpy(
        dtype=np.float64
    )


    (
        mean_gap,
        gap_ci_low,
        gap_ci_high
    ) = bootstrap_mean_ci(

        differences,

        args.bootstrap,

        SEED + 500
    )


    (
        lower_rate,
        lower_ci_low,
        lower_ci_high
    ) = bootstrap_proportion_ci(

        oracle_df[
            "IR_allows_lower"
        ].values,

        args.bootstrap,

        SEED + 600
    )


    p_value = paired_randomization_pvalue(

        differences,

        args.permutations,

        SEED + 700
    )


    mean_ann = oracle_df[
        "min_ANN_safe_ef"
    ].mean()


    mean_ir = oracle_df[
        "min_IR_safe_ef"
    ].mean()


    if mean_ann > 0:

        relative_reduction = (

            mean_ann
            -
            mean_ir

        ) / mean_ann * 100.0

    else:

        relative_reduction = 0.0


    return {

        "task":
            task_name,

        "source":
            source_name,

        "IR_tolerance":
            tolerance,

        "queries":
            len(
                oracle_df
            ),

        "mean_ANN_safe_ef":
            mean_ann,

        "mean_IR_safe_ef":
            mean_ir,

        "mean_ANN_minus_IR_gap":
            mean_gap,

        "gap_95CI_low":
            gap_ci_low,

        "gap_95CI_high":
            gap_ci_high,

        "relative_budget_reduction_%":
            relative_reduction,

        "IR_allows_lower_rate":
            lower_rate,

        "lower_rate_95CI_low":
            lower_ci_low,

        "lower_rate_95CI_high":
            lower_ci_high,

        "same_budget_rate":
            oracle_df[
                "same_budget"
            ].mean(),

        "IR_requires_higher_rate":
            oracle_df[
                "IR_requires_higher"
            ].mean(),

        "paired_randomization_p":
            p_value,

        "ANN_safe_found_rate":
            oracle_df[
                "ANN_safe_found"
            ].mean(),

        "IR_safe_found_rate":
            oracle_df[
                "IR_safe_found"
            ].mean()
    }


