# 24. FIXED-BUDGET VIOLATION CURVES
# ============================================================

def fixed_violation_table(
    df,
    ef_values,
    ann_column,
    ir_loss_column,
    ir_tolerance,
    task_name
):

    rows = []


    for ef in ef_values:

        subset = df[
            df[
                "efSearch"
            ]
            ==
            ef
        ]


        ann_violation = np.mean(

            subset[
                ann_column
            ]
            <
            ANN_TARGET
        )


        ir_violation = np.mean(

            subset[
                ir_loss_column
            ]
            >
            ir_tolerance
        )


        rows.append({

            "task":
                task_name,

            "efSearch":
                ef,

            "ANN_violation_rate":
                ann_violation,

            "IR_violation_rate":
                ir_violation
        })


    return pd.DataFrame(
        rows
    )


